# (name, category, tradition, content) - public-domain / ancient prayers added to fill thin areas.
O = "orthodox"
PA = "protestant,anglican"
A = "anglican"
ALL = "all"
CA = "catholic,anglican"
CO = "catholic,orthodox"

DATA = [
    # ---- Orthodox: morning, evening, liturgy ----
    ("Prayer to the Holy Spirit (O Heavenly King)", "morning", O,
     "O Heavenly King, the Comforter, the Spirit of Truth,\nwho art everywhere present and fillest all things,\ntreasury of blessings and giver of life,\ncome and abide in us,\nand cleanse us from every stain,\nand save our souls, O Good One.\nAmen."),
    ("Morning Prayers: Having Risen from Sleep", "morning", O,
     "Having risen from sleep, I fall down before thee, O Good One,\nand sing to thee, O Mighty One, the angelic hymn:\nHoly, holy, holy art thou, O God.\nThrough the Theotokos, have mercy on us.\n\nThou hast raised me from my bed and from sleep, O Lord;\nlighten my mind and my heart,\nand open my lips that I may praise thee, O Holy Trinity:\nHoly, holy, holy art thou, O God.\nThrough the Theotokos, have mercy on us.\nAmen."),
    ("Prayer Before Sleep (Lord Jesus Christ, Forgive Me)", "evening", O,
     "O Lord our God, forgive me whatever sin I have committed this day\nin word, deed or thought,\nas thou art good and the lover of mankind.\nGrant me peaceful and undisturbed sleep.\nSend thy guardian angel to protect and keep me from every evil;\nfor thou art the guardian of our souls and bodies,\nand to thee we ascribe glory,\nto the Father, and to the Son, and to the Holy Spirit,\nnow and ever, and unto ages of ages.\nAmen."),
    ("Prayer Before Reading Holy Scripture", "morning", O,
     "Shine within our hearts, loving Master, Jesus Christ,\nthe pure light of thy divine knowledge,\nand open the eyes of our minds\nto understand the teachings of thy Gospel.\nPlant in us also reverence for thy blessed commandments,\nthat we may trample down every carnal desire\nand pursue a spiritual life,\nthinking and doing all that is pleasing to thee.\nFor thou art the illumination of our souls and bodies, O Christ our God,\nand to thee we give glory,\nwith thy Father, who is without beginning,\nand thy all-holy, good and life-giving Spirit,\nnow and ever, and unto ages of ages.\nAmen."),
    ("Trisagion Hymn", "mass", O,
     "Holy God, Holy Mighty, Holy Immortal,\nhave mercy on us.\n(Said three times.)\n\nGlory to the Father, and to the Son, and to the Holy Spirit,\nboth now and ever, and unto ages of ages. Amen.\n\nHoly Trinity, have mercy on us.\nLord, cleanse us from our sins.\nMaster, pardon our iniquities.\nHoly One, visit and heal our infirmities, for thy name's sake.\n\nLord, have mercy. (Three times.)"),
    ("The Great Doxology (Glory to Thee Who Hast Shown Us the Light)", "mass", O,
     "Glory to thee, who hast shown us the light.\nGlory to God in the highest, and on earth peace, goodwill among men.\nWe praise thee, we bless thee, we worship thee,\nwe glorify thee, we give thanks to thee for thy great glory.\nO Lord, heavenly King, God the Father Almighty;\nO Lord, the only-begotten Son, Jesus Christ,\nand the Holy Spirit.\nO Lord God, Lamb of God, Son of the Father,\nthat takest away the sin of the world, have mercy on us;\nthou that takest away the sins of the world,\nreceive our prayer.\nThou that sittest at the right hand of the Father, have mercy on us.\nFor thou only art holy, thou only art the Lord, Jesus Christ,\nto the glory of God the Father.\nAmen."),
    ("Prayers Before Holy Communion: I Believe, O Lord, and I Confess", "mass", O,
     "I believe, O Lord, and I confess that thou art truly the Christ,\nthe Son of the living God,\nwho camest into the world to save sinners,\nof whom I am first.\nAnd I believe that this is truly thine own immaculate Body,\nand that this is truly thine own precious Blood.\nTherefore I pray thee: have mercy upon me and forgive my transgressions,\nvoluntary and involuntary, of word and of deed,\nof knowledge and of ignorance.\nAnd make me worthy to partake without condemnation of thine immaculate Mysteries,\nfor the remission of sins and for life everlasting.\nAmen."),
    ("Thanksgiving After Holy Communion", "mass", O,
     "Glory to thee, O God. Glory to thee, O God. Glory to thee, O God.\n\nI thank thee, O Lord my God,\nthat thou hast not rejected me, a sinner,\nbut hast made me worthy to partake of thy holy things.\nI thank thee that thou hast permitted me, the unworthy,\nto partake of thy most pure and heavenly gifts.\nO Master who lovest mankind, who for our sake didst die and rise again\nand didst bestow upon us these awesome and life-giving Mysteries\nfor the well-being and sanctification of our souls and bodies:\nlet them be for the healing of my soul and body,\nthe averting of every evil,\nthe illumination of the eyes of my heart,\nthe peace of my spiritual powers,\na faith unashamed, a love unfeigned,\nthe fullness of wisdom, the keeping of thy commandments,\nthe increase of thy divine grace, and the inheritance of thy kingdom.\nAmen."),
    ("The Litany of Fervent Supplication", "mass", O,
     "Let us all say with our whole soul and with our whole mind, let us say:\nLord, have mercy.\n\nO Lord Almighty, the God of our fathers, we pray thee, hear and have mercy.\nHave mercy on us, O God, according to thy great mercy; we pray thee, hear and have mercy.\nAlso we pray for our Archbishop, and for all our brotherhood in Christ.\nAlso we pray for mercy, life, peace, health and salvation,\nfor the servants of God, and for the forgiveness of their sins.\n\nLord, have mercy. (Three times.)"),
    ("Benediction of the Divine Liturgy (The Dismissal)", "mass", O,
     "Blessed be the name of the Lord, from this time forth and for evermore.\n\nThe blessing of the Lord be upon you,\nthrough his grace and love for mankind,\nalways, now and ever, and unto ages of ages.\nAmen.\n\nGlory to thee, O Christ our God and our hope, glory to thee.\nAmen. Lord, have mercy. (Three times.) Father, give the blessing."),
    ("Prayer of the Third Hour", "morning", O,
     "O Lord, who at the third hour didst send down thy most Holy Spirit\nupon thine apostles:\ntake not that same Spirit from us, O Good One,\nbut renew him within us who pray to thee.\nCreate in me a clean heart, O God,\nand renew a right spirit within me.\nCast me not away from thy presence,\nand take not thy Holy Spirit from me.\nAmen."),

    # ---- Anglican / Protestant: Book of Common Prayer (public domain), Fathers ----
    ("Collect for Purity (Book of Common Prayer)", "mass", PA,
     "Almighty God, unto whom all hearts be open, all desires known,\nand from whom no secrets are hid:\ncleanse the thoughts of our hearts by the inspiration of thy Holy Spirit,\nthat we may perfectly love thee,\nand worthily magnify thy holy Name;\nthrough Christ our Lord.\nAmen."),
    ("Prayer of Saint Chrysostom (Book of Common Prayer)", "morning", PA,
     "Almighty God, who hast given us grace at this time\nwith one accord to make our common supplications unto thee,\nand dost promise that when two or three are gathered together in thy Name\nthou wilt grant their requests:\nfulfil now, O Lord, the desires and petitions of thy servants,\nas may be most expedient for them;\ngranting us in this world knowledge of thy truth,\nand in the age to come life everlasting.\nAmen."),
    ("A Collect for the Presence of Christ (Lighten Our Darkness)", "evening", PA,
     "Lighten our darkness, we beseech thee, O Lord;\nand by thy great mercy defend us from all perils and dangers of this night;\nfor the love of thy only Son, our Saviour, Jesus Christ.\nAmen."),
    ("Collect for the First Sunday of Advent (Book of Common Prayer)", "mass", PA,
     "Almighty God, give us grace that we may cast away the works of darkness,\nand put upon us the armour of light,\nnow in the time of this mortal life,\nin which thy Son Jesus Christ came to visit us in great humility;\nthat in the last day, when he shall come again in his glorious majesty\nto judge both the quick and the dead,\nwe may rise to the life immortal;\nthrough him who liveth and reigneth with thee and the Holy Ghost,\nnow and ever.\nAmen."),
    ("Collect for Christmas Day (Book of Common Prayer)", "mass", PA,
     "Almighty God, who hast given us thy only-begotten Son\nto take our nature upon him, and as at this time to be born of a pure virgin:\ngrant that we, being regenerate, and made thy children by adoption and grace,\nmay daily be renewed by thy Holy Spirit;\nthrough the same our Lord Jesus Christ,\nwho liveth and reigneth with thee and the same Spirit,\nones God, world without end.\nAmen."),
    ("Collect for Ash Wednesday (Book of Common Prayer)", "mass", PA,
     "Almighty and everlasting God, who hatest nothing that thou hast made,\nand dost forgive the sins of all them that are penitent:\ncreate and make in us new and contrite hearts,\nthat we, worthily lamenting our sins\nand acknowledging our wretchedness,\nmay obtain of thee, the God of all mercy,\nperfect remission and forgiveness;\nthrough Jesus Christ our Lord.\nAmen."),
    ("Collect for Easter Day (Book of Common Prayer)", "mass", PA,
     "Almighty God, who through thine only-begotten Son Jesus Christ\nhast overcome death, and opened unto us the gate of everlasting life:\nwe humbly beseech thee that, as by thy special grace preventing us\nthou dost put into our minds good desires,\nso by thy continual help we may bring the same to good effect;\nthrough Jesus Christ our Lord,\nwho liveth and reigneth with thee and the Holy Ghost,\never one God, world without end.\nAmen."),
    ("Collect for Whitsunday (Pentecost)", "mass", PA,
     "God, who as at this time didst teach the hearts of thy faithful people\nby sending to them the light of thy Holy Spirit:\ngrant us by the same Spirit to have a right judgement in all things,\nand evermore to rejoice in his holy comfort;\nthrough the merits of Christ Jesus our Saviour,\nwho liveth and reigneth with thee, in the unity of the same Spirit,\none God, world without end.\nAmen."),
    ("A Prayer for the Church (Book of Common Prayer)", "mass", PA,
     "Almighty and everlasting God, by whose Spirit the whole body of the Church\nis governed and sanctified:\nreceive our supplications and prayers, which we offer before thee\nfor all estates of men in thy holy Church,\nthat every member of the same, in his vocation and ministry,\nmay truly and godly serve thee;\nthrough our Lord and Saviour Jesus Christ.\nAmen."),
    ("A Prayer for All Who Suffer", "devotional", PA,
     "O merciful Father, who hast taught us in thy holy Word\nthat thou dost not willingly afflict or grieve the children of men:\nlook with pity upon the sorrows of thy servants for whom our prayers are offered.\nRemember them, O Lord, in mercy;\nnourish their souls with patience, comfort them with a sense of thy goodness,\nlift up thy countenance upon them, and give them peace;\nthrough Jesus Christ our Lord.\nAmen."),
    ("Grace Before the Day (Prayer of Saint Richard of Chichester)", "morning", ALL,
     "Thanks be to thee, my Lord Jesus Christ,\nfor all the benefits thou hast given me,\nfor all the pains and insults thou hast borne for me.\nO most merciful Redeemer, Friend and Brother,\nmay I know thee more clearly,\nlove thee more dearly,\nand follow thee more nearly,\nday by day.\nAmen."),
    ("Saint Patrick's Breastplate (Christ Be With Me)", "morning", ALL,
     "Christ be with me, Christ before me, Christ behind me,\nChrist in me, Christ beneath me, Christ above me,\nChrist on my right, Christ on my left,\nChrist when I lie down, Christ when I sit down, Christ when I arise,\nChrist in the heart of every one who thinks of me,\nChrist in the mouth of every one who speaks of me,\nChrist in every eye that sees me,\nChrist in every ear that hears me.\nSalvation is of the Lord. Salvation is of the Christ.\nMay thy salvation, O Lord, be ever with us.\nAmen."),
    ("Late Have I Loved Thee (Saint Augustine)", "devotional", ALL,
     "Late have I loved thee, O Beauty so ancient and so new,\nlate have I loved thee!\nThou wert within me, and I outside;\nand there I sought thee.\nThou wert with me, but I was not with thee.\nThou didst call, and cry, and burst my deafness;\nthou didst flash, and shine, and dispel my blindness;\nthou didst breathe fragrance, and I drew in my breath and I pant for thee;\nI tasted, and I hunger and thirst;\nthou didst touch me, and I burned for thy peace.\nAmen."),
    ("A Prayer Before Study (Saint Thomas Aquinas)", "morning", ALL,
     "Grant me, O merciful God, to desire ardently what is pleasing to thee,\nto examine it prudently, to acknowledge it truly,\nand to fulfil it perfectly,\nfor the praise and glory of thy name.\nOrder my life, O God; grant that I may know what thou requirest of me,\nand give me the grace to do it as I ought.\nAmen."),
    ("Let Nothing Disturb You (Saint Teresa of Avila)", "devotional", ALL,
     "Let nothing disturb thee,\nlet nothing frighten thee;\nall things pass away.\nGod never changes.\nPatience obtains all things.\nWhoever has God lacks nothing:\nGod alone suffices.\nAmen."),
    ("Prayer of Saint Francis (Make Me a Channel of Thy Peace)", "morning", ALL,
     "Lord, make me an instrument of thy peace.\nWhere there is hatred, let me sow love;\nwhere there is injury, pardon;\nwhere there is doubt, faith;\nwhere there is despair, hope;\nwhere there is darkness, light;\nand where there is sadness, joy.\nO Divine Master, grant that I may not so much seek\nto be consoled as to console,\nto be understood as to understand,\nto be loved as to love.\nFor it is in giving that we receive,\nit is in pardoning that we are pardoned,\nand it is in dying that we are born to eternal life.\nAmen."),
    ("The Canticle of the Sun (Saint Francis)", "morning", ALL,
     "Most high, all-powerful, good Lord,\nthine are the praise, the glory, the honour and all blessing.\nBe praised, my Lord, for all thy creatures,\nespecially for Brother Sun, who brings us the day and gives us light.\nBe praised, my Lord, for Sister Moon and the stars,\nfor Brother Wind, for air and clouds and every weather,\nfor Sister Water, so useful, humble, precious and chaste,\nfor Brother Fire, by whom thou lightest the night,\nand for our Sister Mother Earth, who feeds and governs us\nand brings forth fruits and flowers.\nPraise and bless my Lord, and give thanks,\nand serve him with great humility.\nAmen."),
    ("A Prayer for the Fruit of the Spirit", "morning", PA,
     "Holy Spirit, make me an instrument of thy grace.\nGrow in me love, joy, peace, patience,\nkindness, goodness, faithfulness, gentleness and self-control,\nthat my life may show that I belong to Christ.\nAmen."),

    # ---- Catholic: a few daily prayers ----
    ("Come, Holy Spirit", "morning", CO,
     "Come, Holy Spirit, fill the hearts of thy faithful\nand kindle in them the fire of thy love.\n\nV. Send forth thy Spirit and they shall be created.\nR. And thou shalt renew the face of the earth.\n\nLet us pray.\nO God, who by the light of the Holy Spirit\ndidst instruct the hearts of the faithful,\ngrant that by the same Holy Spirit we may be truly wise\nand ever rejoice in his consolation,\nthrough Christ our Lord.\nAmen."),
    ("Prayer to Your Guardian Angel", "evening", "catholic,orthodox,anglican",
     "Angel of God, my guardian dear,\nto whom God's love commits me here,\never this night be at my side\nto light and guard, to rule and guide.\nAmen."),
    ("Evening Examination and Act of Thanksgiving", "evening", "catholic,anglican",
     "Lord, I thank thee for the gifts of this day:\nfor life, for family and friends, for work and rest.\nHelp me to see where I have loved well\nand where I have failed to love.\nForgive what I have done wrong, and strengthen me for tomorrow.\nInto thy hands I commend my spirit.\nAmen."),
    ("Prayer to Saint Michael the Archangel", "devotional", CO,
     "Saint Michael the Archangel, defend us in battle.\nBe our protection against the wickedness and snares of the devil.\nMay God rebuke him, we humbly pray;\nand do thou, O Prince of the heavenly host,\nby the power of God, cast into hell Satan,\nand all the evil spirits who prowl about the world\nseeking the ruin of souls.\nAmen."),
    ("Grace Before Meals (Bless Us, O Lord)", "devotional", CA,
     "Bless us, O Lord, and these thy gifts,\nwhich we are about to receive from thy bounty,\nthrough Christ our Lord.\nAmen."),
    ("Grace After Meals", "devotional", CA,
     "We give thee thanks, almighty God,\nfor all thy benefits,\nwho livest and reignest world without end.\nAmen."),

    # ---- Evening: Compline and ancient evening prayers (public domain) ----
    ("Into Thy Hands, O Lord (Compline Responsory)", "evening", ALL,
     "Into thy hands, O Lord, I commend my spirit.\nFor thou hast redeemed me, O Lord, thou God of truth.\n\nKeep me as the apple of an eye.\nHide me under the shadow of thy wings.\n\nGlory to the Father, and to the Son, and to the Holy Spirit.\nInto thy hands, O Lord, I commend my spirit.\nAmen."),
    ("Keep Watch, Dear Lord (Evening Prayer attributed to Saint Augustine)", "evening", ALL,
     "Watch thou, dear Lord, with those who wake, or watch, or weep tonight,\nand give thine angels charge over those who sleep.\nTend the sick, Lord Christ; give rest to the weary,\nbless the dying, soothe the suffering, pity the afflicted,\nshield the joyous; and all for thy love's sake.\nAmen."),
    ("Visit This Place, O Lord (Compline Collect)", "evening", ALL,
     "Visit this place, O Lord, we beseech thee,\nand drive far from it all snares of the enemy;\nlet thy holy angels dwell with us to preserve us in peace;\nand let thy blessing be upon us always;\nthrough Jesus Christ our Lord.\nAmen."),
    ("Before the Ending of the Day (Te Lucis ante Terminum)", "evening", CA,
     "Before the ending of the day,\nCreator of the world, we pray\nthat thou, with thy accustomed grace,\nwouldst be our guard and keeper now.\n\nFrom all ill dreams defend our sight,\nfrom fears and terrors of the night;\nwithhold from us our ghostly foe,\nthat spot of sin we may not know.\n\nO Father, that we ask be done,\nthrough Jesus Christ, thine only Son;\nwho, with the Holy Ghost and thee,\ndoth live and reign eternally.\nAmen."),
]
